"""Tests for `gate.py stale-evidence-ownership`.

A leftover .academic-helper/evidence-ownership.json from a PREVIOUS run of the
same article maps evidence ownership for a thesis the researcher may have
since rejected. Section-writers load it from disk by contract; nothing else
compares it against the current outline. Same class of check as
argument-graph: a script, not reasoning, run right before Step 6.
"""

import hashlib
import json
import os
import subprocess
import sys
import tempfile
import time
import unittest

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
GATE = os.path.join(ROOT_DIR, "src", "scripts", "gate.py")


def run_gate(*args):
    with tempfile.TemporaryDirectory() as ledger_dir:
        return subprocess.run(
            [sys.executable, GATE, *args, "--ledger", os.path.join(ledger_dir, "session-state.json")],
            capture_output=True,
            text=True,
            timeout=30,
        )


class TestStaleEvidenceOwnership(unittest.TestCase):
    def test_missing_evidence_ownership_passes(self):
        """No evidence-ownership.json yet is a different, legitimate state
        (the architect hasn't written it yet) -- not a staleness problem."""
        with tempfile.TemporaryDirectory() as tmpdir:
            outline_path = os.path.join(tmpdir, "outline.json")
            with open(outline_path, "w", encoding="utf-8") as fh:
                json.dump({"units": []}, fh)
            missing_ownership_path = os.path.join(tmpdir, "does-not-exist.json")
            proc = run_gate(
                "stale-evidence-ownership", outline_path,
                "--evidence-ownership", missing_ownership_path, "--json",
            )
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["status"], "pass")

    def test_ownership_written_before_outline_with_matching_hash_passes(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            outline_path = os.path.join(tmpdir, "outline.json")
            outline_content = b'{"units": []}'
            digest = hashlib.sha256(outline_content).hexdigest()
            ownership_path = os.path.join(tmpdir, "evidence-ownership.json")
            with open(ownership_path, "w", encoding="utf-8") as fh:
                json.dump({"outlineSha256": digest}, fh)
            with open(outline_path, "wb") as fh:
                fh.write(outline_content)
            proc = run_gate(
                "stale-evidence-ownership", outline_path,
                "--evidence-ownership", ownership_path, "--json",
            )
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        self.assertEqual(json.loads(proc.stdout)["status"], "pass")

    def test_mismatched_outline_hash_fails(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            outline_path = os.path.join(tmpdir, "outline.json")
            with open(outline_path, "w", encoding="utf-8") as fh:
                json.dump({"units": []}, fh)
            ownership_path = os.path.join(tmpdir, "evidence-ownership.json")
            with open(ownership_path, "w", encoding="utf-8") as fh:
                json.dump({"outlineSha256": "wrong-hash"}, fh)
            proc = run_gate(
                "stale-evidence-ownership", outline_path,
                "--evidence-ownership", ownership_path, "--json",
            )
        self.assertEqual(proc.returncode, 1, proc.stdout + proc.stderr)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["status"], "fail")
        self.assertIn("stale-hash", [v["check"] for v in payload["violations"]])

    def test_missing_outline_is_could_not_run(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            missing_outline_path = os.path.join(tmpdir, "does-not-exist.json")
            ownership_path = os.path.join(tmpdir, "evidence-ownership.json")
            with open(ownership_path, "w", encoding="utf-8") as fh:
                json.dump({}, fh)
            proc = run_gate(
                "stale-evidence-ownership", missing_outline_path,
                "--evidence-ownership", ownership_path, "--json",
            )
        self.assertEqual(proc.returncode, 2, proc.stdout + proc.stderr)


if __name__ == "__main__":
    unittest.main()
